// PXDict's own tables in /data/gateway/pxdict.db (docs/PLAN.md §1). Better Auth's tables live in
// auth-schema.ts (generated by its CLI). dictionaries.owner_user_id and audit_log.actor_user_id carry no
// foreign key: dictionaries are handled explicitly when their owner is deleted (Phase 6), and audit
// entries outlive users. Migrations are generated from both files with
// `npm run db:generate -w @pxdict/gateway` and are append-only.
import { sql } from "drizzle-orm";
import { check, index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { user } from "./auth-schema";

export * from "./auth-schema";

/** created_at / updated_at in Unix milliseconds, filled in by SQLite. */
const timestamp = (name: string) =>
  integer(name, { mode: "timestamp_ms" })
    .notNull()
    .default(sql`(CAST(unixepoch('subsec') * 1000 AS INTEGER))`);

export const dictionaries = sqliteTable(
  "dictionaries",
  {
    /** PXDict's own stable id; also the folder name under DICT_DIR. */
    id: text("id").primaryKey(),
    /** wuDict's id (sha256 of a path, 12 hex chars). Changes when files move; refreshed on rescan. */
    wudictId: text("wudict_id"),
    /** `uuid` from db/<name>/info.txt: stable once indexed, used to re-match after a rescan. */
    wudictUuid: text("wudict_uuid").unique(),
    /** Library folder name under DB_DIR (wuDict appends " (fmt)" on name clashes). */
    libraryDir: text("library_dir"),
    title: text("title").notNull(),
    format: text("format"),
    source: text("source", { enum: ["builtin", "proposal"] }).notNull(),
    visibility: text("visibility", { enum: ["global", "private", "hidden"] })
      .notNull()
      .default("hidden"),
    /** Owner (a user.id) for visibility = 'private'. */
    ownerUserId: text("owner_user_id"),
    /** Allows same-origin (style A) rendering; off by default. */
    trustedRender: integer("trusted_render", { mode: "boolean" }).notNull().default(false),
    sourcePath: text("source_path"),
    sourceBytes: integer("source_bytes"),
    indexBytes: integer("index_bytes"),
    mediaPacked: integer("media_packed", { mode: "boolean" }).notNull().default(false),
    sourceDeletedAt: integer("source_deleted_at", { mode: "timestamp_ms" }),
    /** The proposal this dictionary was approved from (references proposals.id from Phase 6). */
    proposalId: text("proposal_id"),
    createdAt: timestamp("created_at"),
    updatedAt: timestamp("updated_at"),
  },
  (t) => [
    index("dictionaries_wudict_id_idx").on(t.wudictId),
    check("dictionaries_source_check", sql`${t.source} IN ('builtin', 'proposal')`),
    check("dictionaries_visibility_check", sql`${t.visibility} IN ('global', 'private', 'hidden')`),
    check("dictionaries_private_owner_check", sql`${t.visibility} <> 'private' OR ${t.ownerUserId} IS NOT NULL`),
  ],
);

export const auditLog = sqliteTable(
  "audit_log",
  {
    id: integer("id").primaryKey({ autoIncrement: true }),
    /** user.id of the actor; null for the system. Kept without a foreign key so entries outlive users. */
    actorUserId: text("actor_user_id"),
    /** Dotted action name, e.g. "dict.approve", "storage.delete". */
    action: text("action").notNull(),
    targetType: text("target_type"),
    targetId: text("target_id"),
    detailsJson: text("details_json", { mode: "json" }).$type<Record<string, unknown>>(),
    bytesFreed: integer("bytes_freed"),
    createdAt: timestamp("created_at"),
  },
  (t) => [index("audit_log_created_at_idx").on(t.createdAt), index("audit_log_actor_idx").on(t.actorUserId)],
);

/** Single-use registration codes for REGISTRATION=invite. Only the SHA-256 of a code is stored. */
export const invites = sqliteTable(
  "invites",
  {
    id: text("id").primaryKey(),
    codeHash: text("code_hash").notNull().unique(),
    createdBy: text("created_by").references(() => user.id, { onDelete: "set null" }),
    /** Role given to the account created with this code. */
    role: text("role", { enum: ["user", "admin"] }).notNull().default("user"),
    note: text("note"),
    expiresAt: integer("expires_at", { mode: "timestamp_ms" }).notNull(),
    /** Set when a sign-up starts with this code (the code cannot be reused, even if that sign-up fails). */
    usedAt: integer("used_at", { mode: "timestamp_ms" }),
    usedBy: text("used_by").references(() => user.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at"),
  },
  (t) => [
    index("invites_created_at_idx").on(t.createdAt),
    check("invites_role_check", sql`${t.role} IN ('user', 'admin')`),
  ],
);
